package org.xianshen.mumirrorb.action;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.ObjectNode; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.xianshen.mumirrorb.common.exception.BusinessException; import org.xianshen.mumirrorb.pojo.DTO.GrowthAdjustmentDTO; import org.xianshen.mumirrorb.service.GrowthService; import java.util.*;
@Component @RequiredArgsConstructor public class GrowthActionHandler implements ActionHandler { private final GrowthService growth; private final ObjectMapper json; private static final String KIND="growth.adjust";
 public Set<String> kinds(){return Set.of(KIND);} public JsonNode validateAndPreview(UUID user,String kind,JsonNode payload){if(!KIND.equals(kind))throw new IllegalArgumentException("未知成长操作");GrowthAdjustmentDTO dto=json.convertValue(payload,GrowthAdjustmentDTO.class);var overview=growth.overview(user);if(overview.getAxes().stream().noneMatch(a->a.getId().equals(dto.getDimensionId())))throw new BusinessException(400,"未知成长维度");ObjectNode out=json.createObjectNode().put("dimensionId",dto.getDimensionId()).put("points",dto.getPoints()).put("reason",dto.getReason()).put("axesVersion",overview.getAxesVersion());ObjectNode targets=json.createObjectNode();if(dto.getEntryId()!=null){var found=growth.entries(user).stream().map(e->json.convertValue(e,org.xianshen.mumirrorb.pojo.VO.GrowthOverviewVO.Entry.class)).filter(e->Objects.equals(e.getId(),dto.getEntryId())).findFirst().orElseThrow(()->new BusinessException(404,"成长条目不存在"));if(!Objects.equals(found.getVersion(),dto.getExpectedVersion()))throw new BusinessException(409,"成长条目已变化，请刷新");out.put("entryId",dto.getEntryId()).put("targetVersion",found.getVersion());targets.put(String.valueOf(dto.getEntryId()),found.getVersion());}out.set("targetVersions",targets);return out;}
 public void validateEdit(String kind,JsonNode original,JsonNode edited){if(original.has("entryId")&&!original.path("entryId").equals(edited.path("entryId")))throw new BusinessException(400,"更正目标不可更换");}
 public ActionExecution execute(AuthorizedAction action){GrowthAdjustmentDTO dto=json.convertValue(action.getPayload(),GrowthAdjustmentDTO.class);dto.setRequestId(action.getActionId());var result=growth.adjustManual(action.getUserId(),dto);return ActionExecution.applied(json.valueToTree(Map.of("overview",result,"applied",true)));}
}
